#define min(a,b) ((a)<(b)?(a):(b))

int gcd(int a, int b) {
    int i, ret = 1, minval = min(a, b);
    for (i = 2; i <= minval; i++) {
        if (a % i) /* i not divisor of a */
            continue;
        if (b % i == 0) /* i is divisor of both a and b */
            ret = i;
    }
    return ret;
}

int gcd(int a, int b) {
    while (b) { /* if a < b, performs swap */
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

